System.out.println("=== CREATE VIEW employee_overview ===");
stmt.execute("""
    CREATE VIEW employee_overview AS
    SELECT e.id, e.name AS employee_name, d.name AS department_name, e.salary
    FROM employees e
    JOIN departments d ON d.id = e.department_id
    """);
System.out.println("Widok utworzony.");
// Widok laczacy pracownikow z nazwami ich dzialow - bez niego kazdy,
// kto chcialby te dane, musialby sam pisac JOIN. Dzieki widokowi robimy to RAZ.

System.out.println("=== SELECT * FROM employee_overview ===");
print(stmt.executeQuery("SELECT * FROM employee_overview ORDER BY employee_name"));

System.out.println("\n=== Widok + WHERE (tylko dzial IT) ===");
print(stmt.executeQuery("""
    SELECT employee_name, salary
    FROM employee_overview
    WHERE department_name = 'IT'
    ORDER BY salary DESC
    """));
// Od tej pory piszemy SELECT ... FROM employee_overview DOKLADNIE tak
// samo, jakby to byla prawdziwa tabela - baza 'pod spodem' wykona zapisany JOIN.

stmt.execute("INSERT INTO employees VALUES (4, 'Katarzyna Zielinska', 2, 7500)");
System.out.println("=== Widok po dodaniu nowego pracownika (bez zadnej zmiany w widoku!) ===");
print(stmt.executeQuery("SELECT * FROM employee_overview ORDER BY employee_name"));
// Nowy pracownik w tabeli zrodlowej od razu 'pojawia sie' w widoku -
// widok nie przechowuje wlasnej kopii danych, kazde zapytanie wykonuje sie na nowo.
